// Valida o webhook do backend: HMAC-SHA256 sobre `<timestamp>.<body>`.
// Requer expor os headers no nó de webhook e FISCALIZA_N8N_SECRET no env.
// Em caso de assinatura/timestamp inválidos a execução é abortada.
const crypto = require('crypto');
const item = $('Backend Webhook').first().json;
const headers = item.headers ?? item.request?.headers ?? {};
const timestamp = headers['x-fiscaliza-timestamp'];
const signature = (headers['x-fiscaliza-signature'] ?? '').replace(/^sha256=/, '');
if (!timestamp || !signature) throw new Error('Assinatura ausente no webhook do backend');
if (Math.abs(Date.now() - Date.parse(timestamp)) > 5 * 60 * 1000) throw new Error('Timestamp expirado');
const expected = crypto
  .createHmac('sha256', $env.FISCALIZA_N8N_SECRET)
  .update(timestamp + '.' + JSON.stringify(item.body ?? item))
  .digest('hex');
if (signature !== expected) throw new Error('Assinatura inválida no webhook do backend');
return [{ json: item.body ?? item }];

// Constrói o envio UAZAPI. `text`/`phone` vêm do envelope do backend;
// a chave de idempotência evita duplicação externa.
// Variáveis necessárias: UAZAPI_SEND_URL, UAZAPI_TOKEN (credential store).
const delivery = $input.first().json;
return [{
  json: {
    to: delivery.destination?.phone,
    message: delivery.payload?.text ?? '',
    idempotencyKey: delivery.idempotencyKey,
    notificationId: delivery.notificationId,
    notificationType: delivery.notificationType,
    metadata: { source: 'fiscaliza-ai' }
  }
}];

// Informa o backend do envio aceito (SENT) com externalMessageId.
// Variáveis: FISCALIZA_API_URL, FISCALIZA_N8N_SECRET.
const crypto = require('crypto');
const sent = $input.first().json;
const requestBody = JSON.stringify({
  notificationId: sent.json?.notificationId,
  idempotencyKey: sent.json?.idempotencyKey,
  status: 'SENT',
  externalMessageId: sent.json?.externalMessageId ?? null,
  timestamp: new Date().toISOString()
});
const timestamp = new Date().toISOString();
const signature = crypto
  .createHmac('sha256', $env.FISCALIZA_N8N_SECRET)
  .update(timestamp + '.' + requestBody)
  .digest('hex');
return [{
  json: {
    url: $env.FISCALIZA_API_URL + '/integrations/whatsapp/delivery-callback',
    body: requestBody,
    timestamp,
    signature
  }
}];
